  const x = texts[s.id];
  const line = '[' + s.id + '] ' + (s.status === 'suggested' ? 'SUGGESTION, ' : '') + x.kind + (x.date ? ', ' + x.date : '') + (x.subject ? ', subject "' + x.subject + '"' : '') + ':\n' + x.text;
  budget -= line.length;
  return budget > 0 ? line : '';
}).filter(Boolean);
